<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Bars\ProviderResult;use StudPulse\Database\DB;use StudPulse\Http\ApiError;final class GroupRating{private const MEMBER_JOINS="JOIN academic_groups g ON g.id=m.group_id AND g.archived_at IS NULL
        JOIN universities v ON v.id=g.university_id AND v.code='mpei'
        JOIN terms t ON t.id=m.term_id AND t.university_id=g.university_id AND t.archived_at IS NULL
            AND REPLACE(t.academic_year,'/','-')=REPLACE(g.academic_year,'/','-')
            AND UTC_DATE() BETWEEN t.begins_at AND t.ends_at";private const MEMBER_DATES='m.valid_from<=UTC_TIMESTAMP(6) AND m.valid_to>UTC_TIMESTAMP(6) AND m.verified_at<=UTC_TIMESTAMP(6)';private const VISIBILITY="COALESCE(p.preferences->>'$.ratingVisibility', IF(r.visibility='hidden','hidden','grades'))";public static function scope(string$user):?array{$rows=DB::all("SELECT DISTINCT m.group_id,m.term_id,g.canonical_code,t.academic_year,t.season
            FROM group_memberships m ".self::MEMBER_JOINS."
