                VALUES(?,JSON_OBJECT('ratingVisibility',?),0) AS incoming
                ON DUPLICATE KEY UPDATE preferences=JSON_MERGE_PATCH(user_preferences.preferences,incoming.preferences)",[$user,$visibility]);if($visibility==='hidden'){self::erase($user);}elseif($visibility==='average'){DB::run('UPDATE group_rating_profiles SET subjects_json=NULL,absence_count=NULL,attendance_observed_at=NULL WHERE user_id=?',[$user]);}});}public static function erase(string$user):void{try{DB::run('DELETE FROM group_rating_profiles WHERE user_id=?',[$user]);}catch(\PDOException$error){if((int)($error->errorInfo[1]??0)!==1146)throw$error;}}public static function board(array$scope):array{return self::ranked($scope);}public static function card(array$scope,string$user):?array{return self::ranked($scope,$user)[0]??null;}public static function mayView(string$viewer,string$user):bool{$own=self::scope($viewer);$other=self::scope($user);return$own!==null&&$other!==null&&$own['group_id']===$other['group_id']&&$own['term_id']===$other['term_id']&&self::visibility($user)!=='hidden';}private static function ranked(array$scope,?string$target=null):array{$params=[$scope['group_id'],$scope['term_id']];$rows=DB::all("WITH candidates AS (
                SELECT DISTINCT m.user_id,m.group_id,m.term_id,u.display_name
                FROM group_memberships m
                JOIN users u ON u.id=m.user_id AND u.status='active' AND u.provider='bars'
                    AND u.fixture=0 AND u.university_verified_at IS NOT NULL
                WHERE m.group_id=? AND m.term_id=? AND ".self::MEMBER_DATES."
            ), verified AS (
                SELECT m.user_id FROM group_memberships m JOIN candidates c ON c.user_id=m.user_id ".self::MEMBER_JOINS.' WHERE '.self::MEMBER_DATES."
                GROUP BY m.user_id
                HAVING COUNT(DISTINCT m.group_id,m.term_id)=1 AND MAX(m.group_id=c.group_id AND m.term_id=c.term_id)=1
            ), visible AS (
                SELECT c.*,
