                    CASE WHEN r.group_id=c.group_id AND r.term_id=c.term_id THEN r.observed_at END AS observed_at,
                    CASE WHEN r.group_id=c.group_id AND r.term_id=c.term_id AND ".self::VISIBILITY."='grades' THEN r.subjects_json END AS subjects_json,
                    CASE WHEN r.group_id=c.group_id AND r.term_id=c.term_id AND ".self::VISIBILITY."='grades'
