            )
            SELECT * FROM ranked ORDER BY average_score DESC,display_name,user_id",$params);$twos=[];foreach($rows as&$row){$row['subjects']=$row['subjects_json']===null?null:json_decode($row['subjects_json'],true,32,JSON_THROW_ON_ERROR);$row['progress']=$row['subjects']===null?[]:GroupRatingGrades::studyProgress($row['subjects']);if($row['subjects']!==null)$twos[$row['user_id']]=$row['progress']['twos'];}unset($row);$maxTwos=count($twos)>=2?max($twos):0;if($target!==null)$rows=array_filter($rows,static fn(array$row):bool=>$row['user_id']===$target);return array_values(array_map(static function(array$row)use($target,$maxTwos):array{$average=$row['average_score']===null?null:(float)$row['average_score'];$position=$average===null?null:(int)$row['place'];$badges=GroupRatingGrades::achievements($average,$position,(int)$row['scored'],$row['progress']);if($maxTwos>0&&($row['progress']['twos']??null)===$maxTwos)$badges[]='twos';if($row['with_attendance']>=2&&$row['absences']>0&&(int)$row['absences']===(int)$row['max_absences'])$badges[]='mostAbsences';if($row['absences']!==null&&(int)$row['absences']===0)$badges[]='perfectAttendance';$profile=['id'=>$row['user_id'],'name'=>$row['display_name'],'visibility'=>$row['visibility'],'average'=>$average,'position'=>$position,'observedAt'=>$row['observed_at']===null?null:gmdate('c',strtotime($row['observed_at'].' UTC')),'achievements'=>$badges,];if($target!==null&&$row['visibility']==='grades')$profile['subjects']=$row['subjects']??[];return$profile;},$rows));}public static function matchesTerm(array$scope,?string$label):bool{if(!preg_match('~\b(\d{4})\s*[/–-]\s*(\d{4})\s*,?\s*(осенний|весенний|осень|весна)\b~iu',$label??'',$parts))return false;$season=str_starts_with(mb_strtolower($parts[3]),'ос')?'autumn':'spring';$scopeSeason=$scope['season']==='fall'?'autumn':$scope['season'];return str_replace('/','-',$scope['academic_year'])==="$parts[1]-$parts[2]"&&$scopeSeason===$season;}public static function attendanceProgress(string$user,array$scope,ProviderResult$result):?int{$attendance=$result->details['attendance']??[];if($result->fixture||!$result->observedAt||!empty($result->details['stale'])||empty($attendance['summaryAvailable']))return null;$count=(int)$attendance['total'];$bounds=DB::one('SELECT begins_at,ends_at FROM terms WHERE id=?',[$scope['term_id']]);if(!$bounds)return null;$observed=new \DateTimeImmutable($result->observedAt);$day=$observed->setTimezone(new \DateTimeZone('Europe/Moscow'))->format('Y-m-d');if($day<$bounds['begins_at']||$day>$bounds['ends_at'])return null;$dates=array_column($attendance['absences'],'date');if($dates&&(min($dates)<$bounds['begins_at']||max($dates)>$bounds['ends_at']))return null;if($count===0&&($dates||(empty($attendance['summaryFromTotals'])&&empty($attendance['detailsAvailable']))))return null;if($count>0&&count($dates)!==$count)return null;DB::transaction(function()use($user,$scope,$count,$observed):void{DB::one('SELECT id FROM users WHERE id=? FOR UPDATE',[$user]);if(self::visibility($user)!=='grades')return;$at=$observed->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s');DB::run('UPDATE group_rating_profiles SET absence_count=?,attendance_observed_at=?
                WHERE user_id=? AND group_id=? AND term_id=? AND (attendance_observed_at IS NULL OR attendance_observed_at<=?)',[$count,$at,$user,$scope['group_id'],$scope['term_id'],$at]);});return$count;}public static function capture(string$user,ProviderResult$result):void{if($result->fixture||!$result->observedAt||!empty($result->details['stale'])||empty($result->details['semester']))return;try{$data=GroupRatingGrades::summarize($result);$observed=gmdate('Y-m-d H:i:s',strtotime($result->observedAt));DB::transaction(function()use($user,$result,$data,$observed):void{DB::one('SELECT id FROM users WHERE id=? FOR UPDATE',[$user]);$visibility=self::visibility($user);if($visibility==='hidden')return;$scope=self::scope($user);if(!$scope||!self::matchesTerm($scope,$result->details['semester']))return;$previous=DB::one('SELECT group_id,term_id,observed_at FROM group_rating_profiles WHERE user_id=? FOR UPDATE',[$user]);if($previous&&$previous['group_id']===$scope['group_id']&&$previous['term_id']===$scope['term_id']&&$previous['observed_at']!==null&&$previous['observed_at']>$observed)return;$subjects=$visibility==='grades'?json_encode($data['subjects'],JSON_THROW_ON_ERROR|JSON_INVALID_UTF8_SUBSTITUTE):null;DB::run('INSERT INTO group_rating_profiles(user_id,group_id,term_id,visibility,generation,average_score,subjects_json,observed_at)
                    VALUES(?,?,?,?,?,?,CAST(CONVERT(? USING utf8mb4) AS JSON),?) AS incoming
                    ON DUPLICATE KEY UPDATE absence_count=IF(group_rating_profiles.group_id=incoming.group_id
                        AND group_rating_profiles.term_id=incoming.term_id,absence_count,NULL),
                        attendance_observed_at=IF(group_rating_profiles.group_id=incoming.group_id
