                        group_id=incoming.group_id,term_id=incoming.term_id,visibility=incoming.visibility,
                        average_score=incoming.average_score,subjects_json=incoming.subjects_json,observed_at=incoming.observed_at',[$user,$scope['group_id'],$scope['term_id'],$visibility,DB::id(),$data['average'],$subjects,$observed]);});}catch(\PDOException$error){if((int)($error->errorInfo[1]??0)!==1146){error_log('StudPulse group rating snapshot: '.(int)($error->errorInfo[1]??0));}}}}